mapper.update:
UPDATE approval_task SET approver_user_id=#{next},lock_version=lock_version+1,
  updated_at=#{now},updated_by_type='USER',updated_by_id=#{actorId}
WHERE tenant_id=#{tenantId} AND approval_task_id=#{task.approvalTaskId} AND status='PENDING' AND lock_version=#{task.lockVersion}

UPDATE workflow_instance
SET current_level = 2, lock_version = lock_version + 1,
    updated_at = #{now}, updated_by_type = 'USER', updated_by_id = #{actorId}
WHERE tenant_id = #{tenantId} AND workflow_instance_id = #{workflowInstanceId} AND status = 'RUNNING'
  AND current_level = 1 AND lock_version = #{expectedVersion}

UPDATE workflow_instance
SET status = #{status}, current_level = NULL, completed_at = #{now},
    lock_version = lock_version + 1, updated_at = #{now},
    updated_by_type = 'USER', updated_by_id = #{actorId}
WHERE tenant_id = #{tenantId} AND workflow_instance_id = #{workflowInstanceId} AND status = 'RUNNING'
  AND lock_version = #{expectedVersion}

mapper.select:
 WHERE i.tenant_id=#{tenantId}
AND i.status=#{status}AND i.ticket_id=#{ticketId}AND i.workflow_version_id=#{workflowVersionId}
AND EXISTS (SELECT 1 FROM approval_task scope_task WHERE scope_task.tenant_id=i.tenant_id AND scope_task.workflow_instance_id=i.workflow_instance_id AND scope_task.approver_user_id=#{approverUserId})AND (i.started_at  #{cursorStartedAt} OR (i.started_at=#{cursorStartedAt} AND i.workflow_instance_id  #{cursorId}))
ORDER BY i.started_at , i.workflow_instance_id  LIMIT #{limit}

